(lib.sklar = function(mode,startPosition,loop,reversed) {
if (loop == null) { loop = true; }
if (reversed == null) { reversed = false; }
	var props = new Object();
	props.mode = mode;
	props.startPosition = startPosition;
	props.labels = {};
	props.loop = loop;
	props.reversed = reversed;
	cjs.MovieClip.apply(this,[props]);

	this.isSingleFrame = false;
	// timeline functions:
	this.frame_0 = function() {
		if(this.isSingleFrame) {
			return;
		}
		if(this.totalFrames == 1) {
			this.isSingleFrame = true;
		}
		//
		const root = this.parent;
		let saklar1On = false; // awalnya ON
		root.saklar1.rotation = 45;
		
		// Saat saklar1 di klik
		root.saklar1.on("click", () => {
		    saklar1On = !saklar1On; // toggle true/false
		
		    if (saklar1On) {
		        root.saklar1.rotation = 0;  // posisi ON
		    } else {
		        root.saklar1.rotation = 45; // posisi OFF
		        root.kkig.volt = null;      // matikan volt saat OFF
		    }
		});
		
		// Fungsi nyala
		this.nyala = function () {
		    if (root.kkb.volt != null) {
		        root.kkig.volt = root.kkb.volt;
		    }
		};
		
		// Event tick
		this.on("tick", () => {
		    if (saklar1On) {
		        this.nyala();
		    }
		});
	}

	// actions tween:
	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(1));

	// Layer_1
	this.shape = new cjs.Shape();
	this.shape.graphics.f("#000000").s().p("AgbEnIAApNIA3AAIAAJNg");
	this.shape.setTransform(-2.6,1.2,1,1,0,0,0,-2.6,29.3);

	this.shape_1 = new cjs.Shape();
	this.shape_1.graphics.f("#FFFFFF").s().p("AilHxIAAvhIFLAAIAAPhg");
	this.shape_1.setTransform(0.475,-26.625);

	this.timeline.addTween(cjs.Tween.get({}).to({state:[{t:this.shape_1},{t:this.shape}]}).wait(1));

	this._renderFirstFrame();

}).prototype = getMCSymbolPrototype(lib.sklar, new cjs.Rectangle(-16.1,-76.3,33.2,99.4), null);


