	this.titik16.setTransform(-25.85,117.45,0.5161,0.5161);

	this.titik20 = new lib.titik1();
	this.titik20.name = "titik20";
	this.titik20.setTransform(-0.25,1.8,0.5161,0.5161);

	this.shape = new cjs.Shape();
	this.shape.graphics.f().s("#0000FF").ss(1,1,1).p("ACqAAQAAAlgyAZQgyAahGAAQhFAAgygaQgygZAAglQAAgjAygbQAygZBFAAQBGAAAyAZQAyAbAAAjg");

	this.shape_1 = new cjs.Shape();
	this.shape_1.graphics.f("#FFFFFF").s().p("Ah3A+QgzgZAAglQAAgjAzgbQAxgZBGAAQBGAAAzAZQAxAbAAAjQAAAlgxAZQgzAahGAAQhGAAgxgag");

	this.titik15 = new lib.titik1();
	this.titik15.name = "titik15";
	this.titik15.setTransform(26.3,127.3,0.5161,0.5161);

