(lib.rotor_1 = function(mode,startPosition,loop,reversed) {
if (loop == null) { loop = true; }
if (reversed == null) { reversed = false; }
	var props = new Object();
	props.mode = mode;
	props.startPosition = startPosition;
	props.labels = {};
	props.loop = loop;
	props.reversed = reversed;
	cjs.MovieClip.apply(this,[props]);

	this.isSingleFrame = false;
	// timeline functions:
	this.frame_0 = function() {
		if(this.isSingleFrame) {
			return;
		}
		if(this.totalFrames == 1) {
			this.isSingleFrame = true;
		}
		this.garisDasar = new createjs.Shape();
		this.addChild(this.garisDasar);
		
		// Shape untuk animasi strip listrik
		this.garisAnim = new createjs.Shape();
		this.addChild(this.garisAnim);
		
		// Parameter animasi
		this.dashOffset      = 0;
		this.dashSpeed       = 0.5;
		this.dashLength      = 10;
		this.dashGap         = 10;
		this.curvatureFactor = 0.5; // secukupnya
		
		// Konfigurasi arah curve per titik
		this.curveConfig = [];
		
		// Array garis dasar yang **tidak ditampilkan** (hanya animasi muncul)
		this.hideBaseSegments = ["titik2", "titik1"]; // segmen awal titik3→titik4 tidak ditampilkan dasar
		
		const getPoint = (arr, i) => arr[Math.max(0, Math.min(arr.length - 1, i))];
		
		this.nyala = () => {
		    // Ambil titik-titik yang valid
		    let ptsKeys = Object.keys(this)
		        .filter(k => k.startsWith("titik") && this[k] && this[k].x !== undefined)
		        .sort((a,b) => parseInt(a.replace("titik",""),10)-parseInt(b.replace("titik",""),10));
		
		    let pts = ptsKeys.map(k => ({ key:k, x:this[k].x, y:this[k].y }));
		    if (pts.length < 2) return;
		
		    // ---- Garis dasar ----
		    let gDasar = this.garisDasar.graphics;
		    gDasar.clear();
		    gDasar.setStrokeStyle(4, "round", "round")
		         .beginStroke("#000000");
		
		    for (let i=0; i<pts.length-1; i++){
		        let start = pts[i];
		        let end   = pts[i+1];
		
		        let dx = end.x - start.x;
		        let dy = end.y - start.y;
		
		        let sCtrlX = (start.x+end.x)/2;
		        let sCtrlY = (start.y+end.y)/2;
		
		        let config = this.curveConfig.find(c => c.titik === start.key);
		        if(config){
		            let dir = config.curve;
		            let offset = this.curvatureFactor * Math.max(Math.abs(dx), Math.abs(dy));
		            if (Math.abs(dx) > Math.abs(dy)) sCtrlY += (dir==="kanan"? -offset : offset);
		            else sCtrlX += (dir==="kanan"? offset : -offset);
		        }
		
		        // cek jika segmen dasar harus disembunyikan
		        if(this.hideBaseSegments.includes(start.key)) continue;
		
		        gDasar.moveTo(start.x, start.y)
		              .quadraticCurveTo(sCtrlX, sCtrlY, end.x, end.y);
		    }
		    gDasar.endStroke();
		
		    // ---- Garis animasi ----
		    let gAnim = this.garisAnim.graphics;
		    gAnim.clear();
		
		    // tampilkan kondensor jika volt **tidak 12**
		    if (
		        !this.parent || 
		        !this.parent.titik1Platina || this.parent.titik1Platina.volt !== 12 ||
		        !this.parent.minDistributor || this.parent.minDistributor.volt !== 12
		    ) {
		       // this.isiKondensor.visible = false; // muncul
		        return; // tidak lanjut animasi listrik
		    }
		
		    // volt 12 → sembunyikan kondensor dan lanjut animasi listrik
		    //this.isiKondensor.visible = true;
		
		    gAnim.setStrokeStyle(2, "round", "round")
		         .beginStroke("yellow")
		         .setStrokeDash([this.dashLength, this.dashGap], this.dashOffset);
		
		    for (let i=0; i<pts.length-1; i++){
		        let start = pts[i];
		        let end   = pts[i+1];
		
		        let dx = end.x - start.x;
		        let dy = end.y - start.y;
		        let sCtrlX = (start.x+end.x)/2;
		        let sCtrlY = (start.y+end.y)/2;
		
		        let config = this.curveConfig.find(c => c.titik === start.key);
		        if(config){
		            let dir = config.curve;
		            let offset = this.curvatureFactor * Math.max(Math.abs(dx), Math.abs(dy));
		            if (Math.abs(dx) > Math.abs(dy)) sCtrlY += (dir==="kanan"? -offset : offset);
		            else sCtrlX += (dir==="kanan"? offset : -offset);
		        }
		
		        gAnim.moveTo(start.x, start.y)
		             .quadraticCurveTo(sCtrlX, sCtrlY, end.x, end.y);
		    }
		    gAnim.endStroke();
		
		    this.dashOffset += this.dashSpeed;
		};
		
		// update tiap frame
		this.on("tick", () => this.nyala());
	}

	// actions tween:
	this.timeline.addTween(cjs.Tween.get(this).call(this.frame_0).wait(1));

	// Layer_1
	this.titik2 = new lib.titik1();
	this.titik2.name = "titik2";

	this.titik1 = new lib.titik1();
	this.titik1.name = "titik1";
	this.titik1.setTransform(51.2,-48.3);

	this.titik = new lib.titik();
	this.titik.name = "titik";
	this.titik.setTransform(50.8,-49.25,0.5185,0.5185,45);

	this.pusat = new lib.pusat_rotor();
	this.pusat.name = "pusat";
	this.pusat.setTransform(0,0,1.2407,1.2407,44.9985);

	this.rotor = new lib.Symbol18();
	this.rotor.name = "rotor";
	this.rotor.setTransform(0.2,-0.2,1,1,45,0,0,25.9,80);

	this.timeline.addTween(cjs.Tween.get({}).to({state:[{t:this.rotor},{t:this.pusat},{t:this.titik},{t:this.titik1},{t:this.titik2}]}).wait(1));

	this._renderFirstFrame();

}).prototype = getMCSymbolPrototype(lib.rotor_1, new cjs.Rectangle(-38.1,-72.3,110.1,110.5), null);


